import { mkdirSync } from "node:fs";
import path from "node:path";
import { drizzle as drizzlePglite, type PgliteDatabase } from "drizzle-orm/pglite";
import * as schema from "./schema";

/**
 * Database access. DATABASE_URL (Postgres / Supabase) in production; otherwise an embedded PGlite
 * database persisted in PGLITE_DIR (default .data/pglite) so the whole platform runs locally with
 * zero setup. Migrations (./drizzle, generated by drizzle-kit) are applied once on first use.
 */
export type Db = PgliteDatabase<typeof schema>;

const g = globalThis as unknown as { __vdDb?: Promise<Db> };
const MIGRATIONS = path.join(process.cwd(), "drizzle");

async function open(): Promise<Db> {
  const url = process.env.DATABASE_URL;
  if (url) {
    const [{ default: postgres }, { drizzle }, { migrate }] = await Promise.all([
      import("postgres"),
      import("drizzle-orm/postgres-js"),
      import("drizzle-orm/postgres-js/migrator"),
    ]);
    const client = postgres(url, { max: 5, prepare: false });
    const db = drizzle(client, { schema });
    await migrate(db, { migrationsFolder: MIGRATIONS });
    // Query API is identical across drivers; the PGlite type is used as the common surface.
    return db as unknown as Db;
  }
  const [{ PGlite }, { migrate }] = await Promise.all([import("@electric-sql/pglite"), import("drizzle-orm/pglite/migrator")]);
  const dir = process.env.PGLITE_DIR ?? path.join(process.cwd(), ".data", "pglite");
  if (!dir.includes("://")) mkdirSync(dir, { recursive: true });
  const client = new PGlite(dir);
  const db = drizzlePglite(client, { schema });
  await migrate(db, { migrationsFolder: MIGRATIONS });
  return db;
}

export function getDb(): Promise<Db> {
  if (!g.__vdDb) {
    g.__vdDb = open().catch((e) => {
      g.__vdDb = undefined;
      throw e;
    });
  }
  return g.__vdDb;
}

export { schema };
